-- 通过自身携带的 collider trigger, 触发 TimelineController 播放 timeline


---@class FiredByColliderTrigger
---@field timelineControllerBH  Engine.Modules.LuaBehaviour -- TimelineController
local FiredByColliderTrigger = Class('FiredByColliderTrigger')

-- ========================================================

--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程


---@type LuaParametersReader
local LuaParametersReader = import('Game.Utils.LuaParametersReader')

local TimelineController = import('Game.DreamSpace.TimelineControll.TimelineController')

local DreamSpaceLuaUtils = import('Game.DreamSpace.Tools.DreamSpaceLuaUtils')

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Canvas = CS.UnityEngine.Canvas
local Transform = CS.UnityEngine.Transform
local Button = CS.UnityEngine.UI.Button
local RectTransform = CS.UnityEngine.RectTransform
local Vector3 = CS.UnityEngine.Vector3
local Quaternion = CS.UnityEngine.Quaternion
local Color = CS.UnityEngine.Color
local Time = CS.UnityEngine.Time
local Text = CS.UnityEngine.UI.Text
local Image = CS.UnityEngine.UI.Image
local Collider = CS.UnityEngine.Collider
local PlayableDirector = CS.UnityEngine.Playables.PlayableDirector
local CinemachineBrain = CS.Cinemachine.CinemachineBrain


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local LuaParameters = CS.Engine.Modules.LuaParameters


-- ========================================================


function FiredByColliderTrigger:__init()
    self.controller = nil
end


function FiredByColliderTrigger:__delete()
end




function FiredByColliderTrigger:Start()
    KTool.SetActive(self.controller.gameObject, true)

    assert( self.timelineControllerBH )
    self.timelineController = DreamSpaceLuaUtils.GetLuaScr(self.timelineControllerBH.gameObject, "Game.DreamSpace.TimelineControll.TimelineController" )
    assert( self.timelineController )


    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.OnTriggerEnterAction = function(behaviourAction,other_)
            self:OnTriggerEnter(other_)
        end
    end

    -- 本 gameobj 务必绑定 collider
    local collider = KTool.GetComponent(self.controller.gameObject, typeof(Collider))
    assert( collider )
end




function FiredByColliderTrigger:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --


function FiredByColliderTrigger:OnTriggerEnter(other)
    print( "碰到 timeline collider !!! " .. other.name )
    assert( isNotNull(other) )
    if other:CompareTag("Player")  then
        self.timelineController:BeginPlay()
    end
end




return FiredByColliderTrigger
